#pragma once

#include <map>
#include <stdexcept>
#include <string>

namespace mavmoos::test {
// A test-only enum, generated by the source-bound Python selector. No numeric
// expected count or arbitrary allowed message set is accepted from the CLI.
class MissionFixtureShape {
 public:
  explicit MissionFixtureShape(const std::string& name) : m_name(name) {
    if(name!="empty"&&name!="bound_home_only")throw std::runtime_error("unknown pinned mission fixture shape");
  }
  const std::string& name() const { return m_name; }
  unsigned count() const { return m_name=="empty"?0:1; }
  bool allows(unsigned id) const { return id==43||id==47||(id==51&&count()==1); }
  bool complete(const std::map<unsigned,unsigned>& sent) const {
    for(const auto& item:sent)if(!allows(item.first)||item.second==0)return false;
    const auto has=[&](unsigned id){const auto at=sent.find(id);return at!=sent.end()&&at->second>0;};
    return has(43)&&has(47)&&(count()==1?has(51):!has(51));
  }
 private:
  std::string m_name;
};
} // namespace mavmoos::test
